   const result:Record<string,any[]>={};
   if(!wanted.includes("media_assets"))wanted.push("media_assets");
   await Promise.all(wanted.map(async table=>{let query=client.from(table as any).select("*").order("created_at",{ascending:false}).limit(200);if(managedDepartmentId&&table==="departments")query=query.eq("id",managedDepartmentId);else if(managedDepartmentId&&departmentScopedTables.has(table))query=query.eq("department_id",managedDepartmentId);const {data}=await query;result[table]=data??[]}));
   setRelations(result);setDepartments(result.departments??[]);setSpecialties(result.specializations??[]);
