     const paths=Array.from(new Set([row.source_pdf_path,row.storage_path,...(versions??[]).map((version:any)=>version.storage_path)].filter((path:any)=>path&&!/^https?:\/\//i.test(path)))) as string[];
     if(paths.length){const {error:storageError}=await client.storage.from("faculty-public").remove(paths);if(storageError){setNotice("Unable to delete this record. Please try again.");return;}}
