 const publicHref=(row:any,target:Module=module)=>{
   const contentKey=target.key.endsWith("_news")?"news":target.key.endsWith("_events")?"events":target.key;
   const department=departments.find(d=>d.id===row.department_id);
   if(target.key==="services")return "/services";
   if(target.key==="departments")return `/departments/${row.slug}`;
   if(target.key==="specializations")return `/departments/${department?.slug??""}/specialties/${row.slug}`;
   if(target.key==="gallery_albums")return department?`/departments/${department.slug}/gallery/albums/${row.slug}`:`/gallery/${row.slug}`;
   if(department&&["programs","research","news","events","gallery","documents"].includes(contentKey))return `/departments/${department.slug}/${contentKey}/${row.slug||row.id}`;
   if(target.key==="timetables"&&department)return `/departments/${department.slug}/timetables${row.specialization_id?`?specialty=${row.specialization_id}`:""}`;
   return row.slug?`${target.route}/${row.slug}`:target.route;
 };
