 const uploadFolder=managedDepartmentId?`${managedDepartmentId}/${module.table}`:module.table;
 const uploadFile=async(field:Field,file?:File)=>{
   if(!client||!file)return;
   const isImage=field.key.includes("image")||field.key==="image_path"||module.key==="media";
   if(module.key==="timetables"&&(file.type!=="application/pdf"||!file.name.toLowerCase().endsWith(".pdf"))){setNotice("Choose the prepared timetable as a PDF file.");return;}
   if(file.size>20*1024*1024){setNotice("Files must be 20 MB or smaller.");return;}
   if(isImage&&!(["image/jpeg","image/png","image/webp"].includes(file.type))){setNotice("Choose a JPEG, PNG or WebP image.");return;}
   setSaving(true);setNotice("");
   const safe=file.name.toLowerCase().replace(/[^a-z0-9._-]+/g,"-");
   const path=`${uploadFolder}/${Date.now()}-${safe}`;
   const {error}=await client.storage.from("faculty-public").upload(path,file,{upsert:false,contentType:file.type});
   if(error)setNotice("Unable to upload this file. Please try again.");else{const url=client.storage.from("faculty-public").getPublicUrl(path).data.publicUrl;setValue(field.key,url);if(module.table==="documents"){setValue("mime_type",file.type);setValue("file_size_bytes",file.size);setValue("storage_path",url);}if(module.table==="timetables"){setValue("mime_type",file.type);setValue("storage_path",path);setValue("file_url",url);setValue("source_pdf_path",path);setValue("source_file_name",file.name);setValue("version_number",Number(draft.version_number||1)+(editing?.id?1:0));setValue("_sourceSize",file.size);setValue("_sourceUploaded",true);}if(module.table==="media_assets"){setValue("public_url",url);setValue("storage_path",path);setValue("mime_type",file.type);setValue("file_size_bytes",file.size);}if(module.table!=="media_assets"){const {error:libraryError}=await client.from("media_assets" as any).insert({title:file.name,storage_path:path,public_url:url,mime_type:file.type,file_size_bytes:file.size,category:module.label,department_id:draft.department_id||null,specialization_id:draft.specialization_id||null,alt_text:""});if(!libraryError)await loadRelations();}setNotice(module.key==="timetables"?"Prepared timetable file uploaded. Preview and save the timetable record.":"File uploaded to the media library. Save the record to publish it.");}
   setSaving(false);
 };
 const uploadImages=async(field:Field,files?:FileList|null)=>{
   if(!files?.length)return;
   if(field.key!=="image_paths"){await uploadFile(field,files[0]);return;}
   if(!client)return;
   const selected=Array.from(files);
   if(selected.some(file=>file.size>20*1024*1024)){setNotice("Each image must be 20 MB or smaller.");return;}
   if(selected.some(file=>!["image/jpeg","image/png","image/webp"].includes(file.type))){setNotice("Choose JPEG, PNG, or WebP images.");return;}
   setSaving(true);setNotice("");
   try{
     const uploads=await Promise.all(selected.map(async file=>{
       const safe=file.name.toLowerCase().replace(/[^a-z0-9._-]+/g,"-");
       const path=`${uploadFolder}/${Date.now()}-${crypto.randomUUID()}-${safe}`;
       const {error}=await client.storage.from("faculty-public").upload(path,file,{upsert:false,contentType:file.type});
       if(error)throw error;
       const url=client.storage.from("faculty-public").getPublicUrl(path).data.publicUrl;
       return {file,path,url};
     }));
     const existing=Array.isArray(draft.image_paths)?draft.image_paths:String(draft.image_paths||"").split(",").map(value=>value.trim()).filter(Boolean);
     setValue("image_paths",Array.from(new Set([...existing,...uploads.map(upload=>upload.url)])));
     await Promise.all(uploads.map(upload=>client.from("media_assets" as any).insert({title:upload.file.name,storage_path:upload.path,public_url:upload.url,mime_type:upload.file.type,file_size_bytes:upload.file.size,category:module.label,department_id:draft.department_id||null,specialization_id:draft.specialization_id||null,alt_text:""})));
     await loadRelations();setNotice(`${uploads.length} image${uploads.length===1?"":"s"} uploaded. Save the record to publish them.`);
   }catch{setNotice("Unable to upload one or more images. Please try again.");}
   setSaving(false);
 };
